#define PI 3.14159265359

const float block_size = .3;

const float fov = 60.*PI/180.;
const float D = .5/tan(fov/2.);

const float step = .5;
const float threshold = .01;
const float far2 = 1000.;
const float far = sqrt(far2);
const int max_steps = 10000;

const vec4 base_color = vec4(.9, .5, 1., 1.);
const vec4 object_albedo = vec4(1., 1., 1., 1.);
const float object_roughness = .5;
const float specular_exponent = 16.;

const vec3 light_pos = vec3(3., 3., 3.);

const float ambient = .1;
const float occlusion_speed = .015;

const int n_bounces = 16;

vec3 rotate_point(vec3 point, vec3 rot) {
    float ca = cos(rot.x), sa = sin(rot.x);
    float cb = cos(rot.y), sb = sin(rot.y);
    float cc = cos(rot.z), sc = sin(rot.z);

    mat3 x_mat = mat3(1, 0, 0, 0, ca, -sa, 0, sa, ca);
    mat3 y_mat = mat3(cb, 0, sb, 0, 1, 0, -sb, 0, cb);
    mat3 z_mat = mat3(cc, -sc, 0, sc, cc, 0, 0, 0, 1);
    mat3 rot_mat = y_mat * z_mat * x_mat;

    return rot_mat * point;
}

float atan2(float y, float x) {
    if (x == 0.) {
        if (y == 0.) return 0.; // supposed to be undefined but eeh
        if (y < 0.) return -PI*.5;
        return PI*.5;
    }

    float at = atan(y/x);
    if (x > 0.) return at;
    if (y < 0.) return at - PI;
    return at + PI;
}

vec3 bounce(vec3 ray, vec3 normal) {
    return ray - 2.*dot(ray, normal)*normal;
}

vec3 cam_rot() {
    return vec3(.3, iTime*.1, 0.);
}

vec3 cam_pos() {
    vec3 rot = cam_rot();
    return rotate_point(vec3(0., 3., 10.), rot);
}

float get_bar_height(int day) {
    float h = float(day*137 % 143 ^ 17) / 143.;
    h = h*h*3.;
    return h*h + 1.;
}

float max3(float a, float b, float c) {
    return a > b ? a > c ? a : c : b > c ? b : c;
}

float block_sdf(vec3 center, vec3 half_size, vec3 pos, out vec3 normal) {
    // cube
    float dx = abs(pos.x-center.x)-half_size.x;
    float dy = abs(pos.y-center.y)-half_size.y;
    float dz = abs(pos.z-center.z)-half_size.z;

    if (dx > dy) {
         if (dx > dz) {
             normal = vec3(pos.x > 0. ? 1. : -1., 0., 0.);
             return dx;
         }

         normal = vec3(0., 0., pos.z > 0. ? 1. : -1.);
         return dz;
    }
    if (dy > dz) {
         normal = vec3(0., pos.y > 0. ? 1. : -1., 0.);
         return dy;
    }

    normal = vec3(0., 0., pos.z > 0. ? 1. : -1.);
    return dz;
}

float debug_sdf(vec3 pos, out vec3 normal) {
    // modular position
    pos = vec3(mod(pos.x+4., 8.)-4., mod(pos.y+4., 8.)-4., mod(pos.z+4., 8.)-4.);

    // sphere
    normal = normalize(pos);
    //return distance(pos, v_zero) - 2.;

    return block_sdf(vec3(0., 0., 0.), vec3(2., 2., 2.), pos, normal);
}

float skyline_sdf(vec3 pos, out vec3 normal) {
    float min_dist = far2;

    vec3 size = vec3(block_size*.5, 0., block_size*.5);

    // skyline
    for (int i = 0; i < 365; i++) {
        float row = float(i%7);
        float col = float(i/7);

        size.y = get_bar_height(i)*block_size*.5;

        vec3 n;
        float d = block_sdf(vec3((-25.5 + col)*block_size, size.y, -.3 + row*block_size), size, pos, n);

        if (d < min_dist) {
            min_dist = d;
            normal = n;
        }
    }

    // stand blocks

    return min_dist;
}

float sdf(vec3 pos, out vec3 normal, out bool has_escaped) {
    vec3 normal_object;
    float d1 = skyline_sdf(pos, normal_object);

    vec3 normal_escape = -normalize(pos);
    float d2 = far - length(pos);

    if (d1 < d2) {
        normal = normal_object;
        has_escaped = false;
        return d1;
    }

    normal = normal_escape;
    has_escaped = d2 < threshold;
    return d2;
}

bool raymarch(vec3 pos, vec3 ray, out vec3 final_pos, out vec3 normal, out float n_steps) {
    for(int steps = 0; steps < max_steps; steps++) {
        bool has_escaped;
        float d = sdf(pos, normal, has_escaped);

        n_steps = float(steps) + d/threshold; // smoothing
        final_pos = pos;

        if (has_escaped)
            return false;
        if (d < threshold)
            return true;

        pos += ray*d*step;
    }

    n_steps = float(max_steps);
    final_pos = pos;
    return false;
}

vec4 get_color(vec3 pos, vec3 ray) {
    vec4 color = vec4(0., 0., 0., 1.);
    float roughness_product = 1.;

    // blinn-phong 
    vec3 light_dir = normalize(light_pos-pos);
    // or directional light
    //vec3 light_dir = vec3(.707, 0., .707);

    // start at 1 to save a subtraction
    for (int i = 1; i <= n_bounces; i++) {
        vec3 final_pos, normal;
        float n_steps; // floating point for smoothing
        bool hit = raymarch(pos, ray, final_pos, normal, n_steps);

        vec4 diffuse;
        float roughness, occlusion, specular;
        if (hit && i < n_bounces) {
            // hit an object

            // bounce
            pos = final_pos+normal*threshold*step*2.;
            ray = bounce(ray, normal);

            diffuse = object_albedo * clamp(dot(normal, -light_dir), ambient, 1.);
            roughness = object_roughness;

            occlusion = 1. / exp(occlusion_speed * n_steps * step);

            specular = pow(clamp(dot(ray, -light_dir), 0., 1.), specular_exponent) * roughness_product;
        }
        else {
            // hit the border, or timed out
            diffuse = texture(iChannel0, vec2(atan2(normal.z, normal.x)*.5/PI+.5, normal.y*.5+.5));
            roughness = 0.; // 0 to use the skybox color fully
            occlusion = 1.;
            specular = 0.;
        }

        color += diffuse * (1.-roughness) * roughness_product * base_color;
        roughness_product *= roughness*occlusion;

        color += specular;

        if (!hit) break;
    }

    return color;
}

vec3 get_ray(vec2 uv) {
    vec3 pos = normalize(vec3((uv.x-.5)*iResolution.x/iResolution.y, uv.y-.5, -D));

    return rotate_point(pos, cam_rot());
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 ray = get_ray(uv);

    fragColor = get_color(cam_pos(), ray);
}
